{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "http_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT cl.service_name AS caller, cl.attr_k8s_pod_name AS cpod, s.span_name, COUNT(*) AS n, ROUND(quantile_cont(cl.duration,0.5)/1e6,1) AS client_p50_ms, ROUND(quantile_cont(cl.duration,0.95)/1e6,1) AS client_p95_ms, ROUND(quantile_cont(s.duration,0.95)/1e6,1) AS server_p95_ms FROM abnormal_traces cl JOIN abnormal_traces s ON s.parent_span_id = cl.span_id AND s.trace_id = cl.trace_id WHERE s.service_name='ts-route-service' AND s.attr_span_kind='Server' AND cl.attr_span_kind='Client' AND cl.service_name='ts-travel2-service' GROUP BY 1,2,3",
          "claim": "travel2's client GET to route: p50 stays 1.7ms but p95 is 419ms, while route's server span is about 2ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT cl.service_name AS caller, COUNT(*) AS n, ROUND(quantile_cont(cl.duration,0.5)/1e6,1) AS client_p50_ms, ROUND(quantile_cont(cl.duration,0.95)/1e6,1) AS client_p95_ms FROM normal_traces cl JOIN normal_traces s ON s.parent_span_id = cl.span_id AND s.trace_id = cl.trace_id WHERE s.service_name='ts-route-service' AND s.span_name='GET /api/v1/routeservice/routes/{routeId}' AND s.attr_span_kind='Server' AND cl.attr_span_kind='Client' GROUP BY 1",
          "claim": "Before the incident, callers of route's GET routeId had p95 of about 2ms, including travel2 at 2.1ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT cl.service_name AS caller, COUNT(*) AS n, ROUND(quantile_cont(cl.duration,0.5)/1e6,1) AS client_p50_ms, ROUND(quantile_cont(cl.duration,0.95)/1e6,1) AS client_p95_ms FROM abnormal_traces cl JOIN abnormal_traces s ON s.parent_span_id = cl.span_id AND s.trace_id = cl.trace_id WHERE s.service_name='ts-route-service' AND s.span_name='GET /api/v1/routeservice/routes/{routeId}' AND s.attr_span_kind='Server' AND cl.attr_span_kind='Client' GROUP BY 1",
          "claim": "During the incident, only travel2's calls to route's GET routeId are slow (p95 419ms); travel-service calls to the same path stay at 2.1ms."
        },
        {
